-- Icon search: a search box in the macro icon picker. The client gives the
-- picker file IDs only, so icons match by their file name (data.lua, e.g.
-- "spell_fire_fireball") and by the names of the player's spells and items
-- showing them, in the player's language.
--
-- Files of this slice:
--   feature.lua  registration and lifecycle (this file)
--   locales.lua  strings
--   data.lua     every icon's file name (generated by tools/icons.ts)
--   names.lua    what an icon matches: its file name, the player's spells and items
--   picker.lua   the box, and the matching icons in Blizzard's grid

local _, ns = ...

local Icons = ns:RegisterFeature("interface", "icons", {
    order = 3,
    presets = {
        minimal = { enabled = true },
        enhanced = { enabled = true },
    },
})

function Icons:OnEnable()
    self.Picker:Enable()
end

function Icons:OnDisable()
    self.Picker:Disable()
end
